package ratelimit

import (
	"testing"
	"time"
)

func TestBasicAllow(t *testing.T) {
	l := New(5, 1.0)
	for i := 0; i < 5; i++ {
		if !l.Allow() {
			t.Fatalf("Allow() should return true for request %d", i+1)
		}
	}
	// 6th request should fail
	if l.Allow() {
		t.Error("Allow() should return false when bucket is empty")
	}
}

func TestRefill(t *testing.T) {
	l := New(1, 100.0) // refills 100 tokens/sec
	if !l.Allow() {
		t.Fatal("first Allow() should succeed")
	}
	time.Sleep(20 * time.Millisecond)
	if !l.Allow() {
		t.Error("After 20ms at 100/s, should have refilled")
	}
}
